const express = require('express');
const { MongoClient, ObjectId } = require('mongodb');
const { authJwt } = require('../auth');

const router = express.Router();
const client = new MongoClient(process.env.MONGODB_URI);

router.get('/api/exports/:exportId/stream-ndjson', authJwt, async (req, res) => {
  const db = client.db('analytics_warehouse');
  const exportMeta = await db.collection('exports').findOne({
    _id: new ObjectId(req.params.exportId),
    requestedBy: req.user.id
  });
  if (!exportMeta) {
    return res.status(403).json({ error: 'Forbidden: export not found or unauthorized' });
  }

  res.setHeader('Content-Type', 'application/x-ndjson');
  res.setHeader('Transfer-Encoding', 'chunked');

  const cursor = db.collection(exportMeta.targetCollection).find({}).batchSize(100);
  while (await cursor.hasNext()) {
    const doc = await cursor.next();
    res.write(JSON.stringify(doc) + '\n');
  }
  res.end();
});
